package clubinho.ui;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.Base64;

/**
 * Cópia do logo e do ícone do Clubinho dentro do próprio código. Serve de garantia: mesmo que a pasta "resources"
 * não seja encontrada, o logo oficial continua aparecendo. (Arquivo gerado a partir de resources/logo.png e icone.png.)
 */
final class LogoEmbutido {
    private LogoEmbutido() {}

    private static final String[] LOGO = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    };

    private static final String[] ICONE = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    };

    static BufferedImage logo() { return ler(LOGO); }

    static BufferedImage icone() { return ler(ICONE); }

    private static BufferedImage ler(String[] partes) {
        try {
            byte[] bytes = Base64.getDecoder().decode(String.join("", partes));
            return ImageIO.read(new ByteArrayInputStream(bytes));
        } catch (Exception e) {
            return null;
        }
    }
}
